import{_ as t,o,c as r,a5 as s}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"第六章：实现简易 Tree Shaking（只打包被使用的 export）","description":"好！我们正式进入： 🌲 ✅ 本章目标： 分析哪些导出（export）被用到了 移除未被使用的 export 减少打包体积，模拟 Rollup 的 Tree Shaking 功能 💡 为什么 Tree Shaking 有用？ 当我们只使用模块的一部分时，比如： import \\\\{。","frontmatter":{"title":"第六章：实现简易 Tree Shaking（只打包被使用的 export）","date":"2026-08-11T00:00:00.000Z","categories":["JavaScript 系统教程"],"tags":["JavaScript","前端","教程","OneNote","模块化与工程化"],"description":"好！我们正式进入： 🌲 ✅ 本章目标： 分析哪些导出（export）被用到了 移除未被使用的 export 减少打包体积，模拟 Rollup 的 Tree Shaking 功能 💡 为什么 Tree Shaking 有用？ 当我们只使用模块的一部分时，比如： import \\\\{。","sidebarWeight":46,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/b-原生js/12-模块化编程/实现esmodule/第六章：实现简易 Tree Shaking（只打包被使用的 export）.md"},"headers":[],"relativePath":"posts/JavaScript系统教程/06-模块化与工程化/实现esmodule/第六章：实现简易 Tree Shaking（只打包被使用的 export）.md","filePath":"posts/JavaScript系统教程/06-模块化与工程化/实现esmodule/第六章：实现简易 Tree Shaking（只打包被使用的 export）.md"}'),n={name:"posts/JavaScript系统教程/06-模块化与工程化/实现esmodule/第六章：实现简易 Tree Shaking（只打包被使用的 export）.md"};function a(p,e,d,g,i,l){return o(),r("div",null,[...e[0]||(e[0]=[s('<div><h1 id="第六章-实现简易-tree-shaking-只打包被使用的-export" tabindex="-1">第六章：实现简易 Tree Shaking（只打包被使用的 export） <a class="header-anchor" href="#第六章-实现简易-tree-shaking-只打包被使用的-export" aria-label="Permalink to &quot;第六章：实现简易 Tree Shaking（只打包被使用的 export）&quot;">​</a></h1><blockquote><p>本节目标：理解“第六章：实现简易 Tree Shaking（只打包被使用的 export）”的核心思路，并能把它用于实际开发或面试表达。 好！我们正式进入：</p></blockquote><p><strong>🌲</strong> ✅ 本章目标：</p><ul><li>分析哪些导出（export）被用到了</li><li>移除未被使用的 export</li><li>减少打包体积，模拟 Rollup 的 Tree Shaking 功能</li></ul><p><strong>💡</strong> <strong>为什么 Tree Shaking 有用？</strong> 当我们只使用模块的一部分时，比如： import { used } from &#39;./utils.mjs&#39;; 如果 utils.mjs 中还 export 了很多函数（但都没用到），我们希望打包结果中 <strong>不要包含它们</strong>。</p><p><strong>🧠</strong> <strong>实现思路：</strong></p><ol><li>用 <strong>acorn</strong> 解析 AST</li><li>找出每个模块的 export 项（记录下来）</li><li>找出被 import 使用的项</li><li>在打包代码中，<strong>移除未被用到的 export</strong></li></ol><p><strong>🛠️</strong> <strong>代码准备</strong> 我们继续在 esbundler/ 中添加如下文件： <strong>📄</strong> <strong>src/utils.mjs</strong> export const used = &#39;I am used&#39;;export const unused = &#39;I should be removed&#39;; <strong>📄</strong> <strong>src/main.mjs</strong> import { used } from &#39;./utils.mjs&#39;;console.log(used);</p><p><strong>📦</strong> <strong>修改 bundler.js —— 实现 Tree Shaking</strong> 我们重点修改两处： <strong>✅</strong> <strong>1. 新增 helper 函数：提取 used export</strong> 在 bundler.js 顶部添加： function analyzeUsedExports(code) { const ast = acorn.parse(code, { ecmaVersion: &#39;latest&#39;, sourceType: &#39;module&#39; }); const usedImports = []; for (const node of ast.body) { if (node.type === &#39;ImportDeclaration&#39;) { node.specifiers.forEach(spec =&gt; { if (spec.type === &#39;ImportSpecifier&#39;) { usedImports.push(spec.imported.name); } }); } } return usedImports;} function removeUnusedExports(code, used) { const exportRegex = /export\\s+const\\s+(\\w+)\\s*=\\s*(.*?);/g; return code.replace(exportRegex, (_, name, value) =&gt; { return used.includes(name) ? <code>const ${name} = ${value};\\nexports.${name} = ${name};</code> : &#39;&#39;; });}</p><p><strong>✅</strong> <strong>2. 替换 parseModule 函数</strong> 找到 parseModule(filePath) 并修改为： function parseModule(filePath) { const absPath = path.resolve(__dirname, filePath); const code = fs.readFileSync(absPath, &#39;utf-8&#39;); const ast = acorn.parse(code, { sourceType: &#39;module&#39;, ecmaVersion: &#39;latest&#39; }); const deps = []; ast.body.forEach(node =&gt; { if (node.type === &#39;ImportDeclaration&#39;) { deps.push(node.source.value); } }); // Tree Shaking：分析用到哪些 export const usedExports = analyzeUsedExports(code); return { id: id++, filePath, rawCode: code, deps, usedExports };}</p><p><strong>✅</strong> <strong>3. 修改打包生成逻辑：把代码处理成导出形式</strong> 在 bundle(graph) 中找到： ${mod.code} 替换为： ${removeUnusedExports(mod.rawCode, mod.usedExports)}</p><p><strong>🚀</strong> <strong>打包并运行</strong> node bundler.jsnode dist/bundle.js</p><p><strong>✅</strong> <strong>输出结果</strong> I am used 并且打包结果中不会出现 unused = &#39;I should be removed&#39;。</p><p><strong>🧾</strong> <strong>输出结果文件预览（部分）</strong> const used = &#39;I am used&#39;;exports.used = used;</p><p><strong>✅</strong> <strong>本章功能总结</strong></p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>能力</strong></td><td><strong>实现</strong></td></tr><tr><td>静态分析导入的 export 名称</td><td>✔</td></tr><tr><td>过滤未用 export</td><td>✔</td></tr><tr><td>仅保留实际需要的代码</td><td>✔</td></tr><tr><td>模拟 Tree Shaking</td><td>✔</td></tr></tbody></table><p><strong>🔮</strong> <strong>下一章预告（第七章）</strong> 我们可以继续挑战更难的功能，比如： <strong>实现 top-level await 支持和异步模块加载</strong> 让这种写法能正确处理： // a.mjsawait new Promise(r =&gt; setTimeout(r, 1000));export const foo = &#39;done&#39;; 需要我们修改执行引擎支持 async/await 模块执行顺序。</p><p>继续进入第七章吗？我可以带你完整实现 top-level await 加载器 🚀 &gt; 来自 &lt;<a href="https://chatgpt.com/c/6805aef6-e7b4-8004-ab43-9a137f666985" target="_blank" rel="noreferrer">https://chatgpt.com/c/6805aef6-e7b4-8004-ab43-9a137f666985</a>&gt;</p></div>',1)])])}const m=t(n,[["render",a]]);export{u as __pageData,m as default};
